You seem to be mixing JavaScript and TypeScript code. In JavaScript, you would call the fetch function directly instead of requests.get. Also, defining Promises and asynchronous functions should be separated normally. Here is a corrected version:

```typescript
import axios from 'axios';

async function fetchUserIds(ids: number[]): Promise<string[]> {
  const validIds = ids.filter(id => id > 0);
  const promises = validIds.map(async (id: number) => {
    const response = await axios.get(`/api/users/${id}`);
    return response.data.username;
  });
  const results = await Promise.all(promises);

  return results;
}
